sqlMap.select:
select es.first_name as first_name, apr.application_number as application_number, marks_percentage as marksPercentage,marks_obtained as marksObtained, total_marks as totalMarks,percentile_n as score,stt.description as componentID ,
CASE WHEN sas.marksstatus = 'V' THEN "Verified" WHEN sas.marksstatus = 'W' THEN "Wrong Marks" ELSE "Not Checked" END as verificationStatusCode,
sas.reason as verificationStatusDesc from applicant_program_registration apr join student_call_list scl on apr.registration_number=scl.registration_number join component_description stt on stt.component_id=scl.component_id join entity_student es on es.application_number=apr.application_number join student_application_status sas on sas.application_number=apr.application_number where apr.application_number=#application_number# group by scl.component_id;

select TestId as docId ,RollNo as application_number ,FileName as file_name
from omr.student_result_info where RollNo=#application_number#
group by TestId;
